-- Real SteelSeries GG Moments schema (tables used by the importer).
CREATE TABLE moments_clips(id UUID PRIMARY KEY UNIQUE, name TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', path TEXT NOT NULL DEFAULT '', clip_start_point REAL NOT NULL DEFAULT 0.0, clip_end_point REAL NOT NULL DEFAULT 0.0, is_autoclipped_legacy INTEGER NOT NULL DEFAULT 0, is_manually_trimmed INTEGER NOT NULL DEFAULT 0, framerate INTEGER NOT NULL DEFAULT 0, audio_bitrate INTEGER NOT NULL DEFAULT 0, audio_samplerate INTEGER NOT NULL DEFAULT 0, video_bitrate INTEGER NOT NULL DEFAULT 0, resolution_height INTEGER NOT NULL DEFAULT 0, resolution_width INTEGER NOT NULL DEFAULT 0, recording_timestamp TEXT NOT NULL DEFAULT '', last_edit_timestamp TEXT NOT NULL DEFAULT '', trimmed_clip_path TEXT NOT NULL DEFAULT '', library_game_unique_id TEXT NOT NULL DEFAULT '', last_game_name TEXT NOT NULL DEFAULT '', keyframes TEXT NOT NULL DEFAULT '[]', full_length REAL NOT NULL DEFAULT 0.0, filesize INTEGER NOT NULL DEFAULT 0, trimmed_filesize INTEGER NOT NULL DEFAULT 0, thumbnail_path TEXT NOT NULL DEFAULT '', gamesense_events TEXT NOT NULL DEFAULT '[]', is_processing INTEGER NOT NULL DEFAULT 0, is_deleted INTEGER NOT NULL DEFAULT 0, tags TEXT NOT NULL DEFAULT '[]', effects text default '[]' not null, last_view_timestamp text default '' not null, effects_schema_version int default 0, file_resolution_height int default 0, file_resolution_width int default 0, trigger_name TEXT NOT NULL DEFAULT '', session_id TEXT default '0', audio_tracks_props TEXT NOT NULL DEFAULT '[]', audio_drop REAL NOT NULL DEFAULT 0, video_drop REAL NOT NULL DEFAULT 0, trigger_type TEXT NOT NULL DEFAULT '', last_user_edit_timestamp text default '', gsdk_version text default '', capture_mode text default '' not null, video_audio_last_ts_diff real default 0 not null, duplicated_frames_count int default 0 not null, crop_format TEXT NOT NULL DEFAULT '', crop_top_left TEXT NOT NULL DEFAULT '');
CREATE TABLE moments_games(id INTEGER PRIMARY KEY AUTOINCREMENT UNIQUE, name TEXT NOT NULL DEFAULT '', path TEXT NOT NULL DEFAULT '', launcher_executables TEXT NOT NULL DEFAULT '[]', library_path TEXT NOT NULL DEFAULT '', library_game_unique_id TEXT NOT NULL DEFAULT '', storefront_id INTEGER NOT NULL DEFAULT 0, capture_enabled INTEGER NOT NULL DEFAULT 1, is_installed INTEGER NOT NULL DEFAULT 1, recording_mode integer default (2) not null);
CREATE TABLE moments_settings(id INTEGER PRIMARY KEY AUTOINCREMENT UNIQUE, key TEXT NOT NULL DEFAULT '', value TEXT NOT NULL DEFAULT '');
